#include "field_qq.hpp"
int main(int argc,char**argv){fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream fs(argv[1]);int nf;fs>>nf;vector<Rat>ff(nf);for(auto&v:ff)readpoly(fs,v.n);ifstream in(argv[2]);int n;in>>n;ofstream out(argv[3]);for(int z=0;z<n;z++){int id;long nn;in>>id>>nn;string cs;int exponent;for(long j=0;j<nn;j++){in>>cs;for(int k=0;k<16;k++)in>>exponent;}long nd;in>>nd;Rat den,g,q;fmpq_t cf;fmpq_init(cf);ulong ex[2];for(long j=0;j<nd;j++){in>>cs>>ex[0]>>ex[1];assert(!fmpq_set_str(cf,cs.c_str(),10));fmpq_canonicalise(cf);for(int k=0;k<14;k++){in>>exponent;assert(exponent==0);}fmpq_mpoly_push_term_fmpq_ui(den.n,cf,ex,ctx);}fmpq_mpoly_sort_terms(den.n,ctx);fmpq_mpoly_combine_like_terms(den.n,ctx);for(auto&f:ff)while(true){assert(fmpq_mpoly_gcd(g.n,den.n,f.n,ctx));if(fmpq_mpoly_total_degree_si(g.n,ctx)<=0)break;assert(fmpq_mpoly_divides(q.n,den.n,g.n,ctx));fmpq_mpoly_swap(q.n,den.n,ctx);}assert(fmpq_mpoly_degree_si(den.n,1,ctx)<=0);out<<id<<'\n';writepoly(out,den.n);cerr<<id<<" remaining e degree "<<fmpq_mpoly_degree_si(den.n,0,ctx)<<'\n';fmpq_clear(cf);}}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
